float vrchParticleHash(vec2 point) {
  return fract(sin(dot(point, vec2(127.1, 311.7))) * 43758.5453);
}
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 resolution = max(iResolution.xy, vec2(1.0));
  vec2 uv = fragCoord / resolution;
  vec4 image = vrchSampleSource0(uv);
  vec2 aspect = vec2(resolution.x / resolution.y, 1.0);
  vec2 field = uv * aspect * uParam_density;
  vec2 cell = floor(field);
  vec2 local = fract(field) - 0.5;
  float seed = vrchParticleHash(cell);
  float particleActive = step(0.78, seed);
  float phase = seed * 6.28318530718;
  vec2 drift = vec2(sin(iTime * uParam_speed + phase), cos(iTime * uParam_speed * 0.73 + phase * 1.31)) * 0.16;
  float radius = uParam_size * mix(0.55, 1.25, vrchParticleHash(cell + 19.7));
  float distanceToParticle = length(local - drift);
  float antialias = max(fwidth(distanceToParticle) * 1.5, 0.002);
  float core = 1.0 - smoothstep(radius, radius + antialias, distanceToParticle);
  float halo = 1.0 - smoothstep(radius * 1.8, radius * (3.6 + uParam_glow * 2.0) + antialias, distanceToParticle);
  float mask = particleActive * clamp(core + halo * uParam_glow * 0.32, 0.0, 1.0);
  vec3 treated = image.rgb + uParam_color.rgb * mask * uParam_brightness;
  fragColor = vec4(mix(image.rgb, treated, uParam_amount), image.a);
}
